out.globalFile:
{
  "theme": "light",
  "compaction": {
    "enabled": false,
    "custom": 1
  },
  "unknownKey": {
    "a": 1
  },
  "float": 1,
  "defaultProvider": "openai",
  "defaultModel": "gpt-5.5",
  "modelThinkingLevels": {
    "openai/gpt-5.5": "high"
  },
  "terminal": {
    "showImages": false,
    "imageWidthCells": 12,
    "clearOnShrink": true
  },
  "markdown": {
    "mermaid": "final"
  },
  "packages": [
    "npm:x",
    {
      "source": "./local",
      "extensions": []
    }
  ],
  "shellPath": "~/bin/zsh",
  "httpIdleTimeoutMs": 1234,
  "fullscreenWheelScrollLines": 100,
  "editorPaddingX": 3,
  "autocompleteMaxVisible": 3,
  "steeringMode": "all",
  "quietStartup": "header",
  "npmCommand": [
    "pnpm"
  ],
  "warnings": {
    "anthropicExtraUsage": false
  },
  "retry": {
    "enabled": false
  },
  "images": {
    "blockImages": true
  },
  "outputPad": 0,
  "treeFilterMode": "labeled-only",
  "defaultProjectTrust": "never"
}
